cypress_script:
describe('Multi-level Dropdown Navigation Menu', () => {
  it('should navigate to Downloads when clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').contains('Downloads').click();
    cy.url().should('include', '/download/jqueryui/menu/menu.pdf');
  });

  it('should not allow interaction with disabled menu item', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#ui-id-1').should('be.visible');
    cy.get('#ui-id-1').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/jqueryui/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level Dropdown Navigation Menu', () => {
  test('should navigate to Downloads when clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.click('text=Downloads');
    await expect(page).toHaveURL(/\/download\/jqueryui\/menu\/menu.pdf/);
  });

  test('should not allow interaction with disabled menu item', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await expect(page.locator('#ui-id-1')).toBeVisible();
    await page.click('#ui-id-1');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/jqueryui/menu');
  });
});
